    if (!mob) { const r = hero.getBoundingClientRect(); hero.dispatchEvent(new PointerEvent('pointermove', { clientX: r.right - 50, clientY: r.top + 40 })); await sleep(100); o.push(`parallax → covers ${cvWrap.style.transform}`); hero.dispatchEvent(new PointerEvent('pointerleave')); }
    o.push(`category rows=${rows.length} panels=${rows.map((w) => w.rs.firstChild.style.background).join(', ')}; tile parts: heart=${!!rows[0].querySelector('.ph-tl .hr')} price="${rows[0].querySelector('.ph-pr span').textContent}" View Product=${!!rows[0].querySelector('.vp')} + bg=${cs(rows[0].querySelector('.ad')).backgroundColor}`);
    const w = rows[1]; w.rs.style.scrollBehavior = 'auto'; const s0 = w.rs.scrollLeft; w.r.click(); await sleep(300); o.push(`row → arrow scrollLeft ${s0} → ${Math.round(w.rs.scrollLeft)} (left arrow enabled=${!w.l.disabled})`); w.l.click(); await sleep(300); w.rs.style.scrollBehavior = ''; w.upd();
    rows[0].querySelector('.ad').click(); await sleep(50); o.push(`yellow + → bag badge "${bagN.textContent}"`);
    if (!mob) { booksA.dispatchEvent(new MouseEvent('mouseenter')); await sleep(280); o.push(`hover Books → mega opacity=${cs(mg).opacity} list=${mg.querySelectorAll('.ls a').length} links, promo cards=${[...mg.querySelectorAll('.ph-pc .tx')].map((t) => t.style.background).join(' / ')}`); setMega(false); await sleep(250); }
    else { mbB.click(); await sleep(350); o.push(`390px hamburger → menu links=${mn.children.length}`); setMenu(false); await sleep(300); }
    srB.click(); if (mob) setSearch(true); await sleep(300); o.push(`search panel opacity=${cs(sr).opacity} input bg=${cs(sIn.parentNode).backgroundColor} default: "${sBody.querySelector('h6').textContent}" ${sBody.querySelectorAll('.ls a').length} stories + "${sBody.querySelector('h5').textContent}" ${sBody.querySelectorAll('.ph-sp').length} cards`);
